BEGIN; CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.updated_at=CURRENT_TIMESTAMP;RETURN NEW;END$$;
CREATE TABLE obras(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),codigo VARCHAR(50) UNIQUE NOT NULL,nome VARCHAR(255) NOT NULL,descricao TEXT,status VARCHAR(20) NOT NULL DEFAULT 'ATIVA' CHECK(status IN('ATIVA','INATIVA')),data_inicio DATE,data_fim DATE CHECK(data_fim IS NULL OR data_inicio IS NULL OR data_fim>=data_inicio),observacoes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE funcionarios(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),nome VARCHAR(255) NOT NULL,matricula VARCHAR(50) UNIQUE,cargo VARCHAR(100),status VARCHAR(20) NOT NULL DEFAULT 'ATIVO' CHECK(status IN('ATIVO','INATIVO')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE prefixos_frota(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),codigo VARCHAR(10) UNIQUE NOT NULL CHECK(codigo=upper(codigo) AND codigo!~'\s' AND codigo<>''),descricao VARCHAR(255),status VARCHAR(20) NOT NULL DEFAULT 'ATIVO' CHECK(status IN('ATIVO','INATIVO')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE FUNCTION norm_prefixo() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.codigo=upper(regexp_replace(NEW.codigo,'\s+','','g'));RETURN NEW;END$$; CREATE TRIGGER prefixo_norm BEFORE INSERT OR UPDATE OF codigo ON prefixos_frota FOR EACH ROW EXECUTE FUNCTION norm_prefixo();
CREATE TABLE ordens_servico(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),numero_os BIGINT UNIQUE NOT NULL,obra_id UUID NOT NULL REFERENCES obras ON DELETE RESTRICT,prefixo_frota_id UUID NOT NULL REFERENCES prefixos_frota ON DELETE RESTRICT,frota_numero INTEGER NOT NULL CHECK(frota_numero>0),natureza_os VARCHAR(20) NOT NULL CHECK(natureza_os IN('INTERNA','TERCEIRO','MATERIAL')),categoria_servico VARCHAR(50) CHECK(categoria_servico IS NULL OR categoria_servico IN('MECANICA','AUTO_ELETRICA','BORRACHARIA','LUBRIFICACAO','SOLDAGEM','FUNILARIA','HIDRAULICA','OUTROS')),prestador_terceiro VARCHAR(255),data_abertura DATE NOT NULL,data_fechamento DATE CHECK(data_fechamento IS NULL OR data_fechamento>=data_abertura),status VARCHAR(30) NOT NULL DEFAULT 'ABERTA' CHECK(status IN('ABERTA','EM_ANDAMENTO','AGUARDANDO_PECA','FINALIZADA','CANCELADA')),observacoes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ordens_servico_funcionarios(ordem_servico_id UUID REFERENCES ordens_servico ON DELETE CASCADE,funcionario_id UUID REFERENCES funcionarios ON DELETE RESTRICT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(ordem_servico_id,funcionario_id));
CREATE TABLE servicos_os(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),ordem_servico_id UUID NOT NULL REFERENCES ordens_servico ON DELETE CASCADE,descricao TEXT NOT NULL,valor NUMERIC(12,2) NOT NULL CHECK(valor>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE produtos_os(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),ordem_servico_id UUID NOT NULL REFERENCES ordens_servico ON DELETE CASCADE,descricao TEXT NOT NULL,quantidade NUMERIC(12,3) NOT NULL CHECK(quantidade>0),unidade VARCHAR(20) NOT NULL,valor_unitario NUMERIC(12,2) NOT NULL CHECK(valor_unitario>=0),valor_total NUMERIC(14,2) GENERATED ALWAYS AS(round(quantidade*valor_unitario,2)) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ON obras(status);CREATE INDEX ON funcionarios(nome);CREATE INDEX ON funcionarios(status);CREATE INDEX ON prefixos_frota(status);CREATE INDEX ON ordens_servico(obra_id);CREATE INDEX ON ordens_servico(prefixo_frota_id);CREATE INDEX ON ordens_servico(data_abertura);CREATE INDEX ON ordens_servico(status);CREATE INDEX ON ordens_servico(natureza_os);CREATE INDEX ON ordens_servico(categoria_servico);CREATE INDEX ON ordens_servico(prestador_terceiro);CREATE INDEX ON ordens_servico(obra_id,data_abertura);CREATE INDEX ON ordens_servico(prefixo_frota_id,frota_numero,data_abertura);CREATE INDEX ON ordens_servico(status,data_abertura);CREATE INDEX ON ordens_servico(natureza_os,categoria_servico,data_abertura);CREATE INDEX ON ordens_servico_funcionarios(funcionario_id);CREATE INDEX ON servicos_os(ordem_servico_id);CREATE INDEX ON produtos_os(ordem_servico_id);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['obras','funcionarios','prefixos_frota','ordens_servico','servicos_os','produtos_os'] LOOP EXECUTE format('CREATE TRIGGER trg_%s_updated BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION set_updated_at()',t,t);END LOOP;END$$;
CREATE VIEW vw_ordens_servico_resumo AS WITH s AS(SELECT ordem_servico_id,sum(valor) v FROM servicos_os GROUP BY 1),p AS(SELECT ordem_servico_id,sum(valor_total) v FROM produtos_os GROUP BY 1) SELECT x.*,CASE WHEN natureza_os='INTERNA' THEN sv ELSE 0 END total_mao_obra_interna,CASE WHEN natureza_os='TERCEIRO' THEN sv ELSE 0 END total_servicos_terceiros,pv total_produtos,(CASE WHEN natureza_os IN('INTERNA','TERCEIRO') THEN sv ELSE 0 END)+pv total_os FROM(SELECT os.id,os.numero_os,os.obra_id,o.codigo obra_codigo,o.nome obra_nome,os.prefixo_frota_id,pf.codigo frota_prefixo,os.frota_numero,pf.codigo||os.frota_numero frota_codigo,os.natureza_os,os.categoria_servico,os.prestador_terceiro,os.data_abertura,os.data_fechamento,os.status,coalesce(s.v,0) sv,coalesce(p.v,0) pv,os.observacoes,os.created_at,os.updated_at FROM ordens_servico os JOIN obras o ON o.id=os.obra_id JOIN prefixos_frota pf ON pf.id=os.prefixo_frota_id LEFT JOIN s ON s.ordem_servico_id=os.id LEFT JOIN p ON p.ordem_servico_id=os.id)x;
CREATE VIEW vw_gastos_obra_frota AS SELECT obra_id,obra_codigo,obra_nome,prefixo_frota_id,frota_prefixo,frota_numero,frota_codigo,count(*) quantidade_os,sum(total_mao_obra_interna) total_mao_obra_interna,sum(total_servicos_terceiros) total_servicos_terceiros,sum(total_produtos) total_produtos,sum(total_os) total_gasto FROM vw_ordens_servico_resumo WHERE status<>'CANCELADA' GROUP BY 1,2,3,4,5,6,7;
CREATE VIEW vw_gastos_obra AS SELECT obra_id,obra_codigo,obra_nome,count(*) quantidade_os,sum(total_mao_obra_interna) total_mao_obra_interna,sum(total_servicos_terceiros) total_servicos_terceiros,sum(total_produtos) total_produtos,sum(total_os) total_gasto FROM vw_ordens_servico_resumo WHERE status<>'CANCELADA' GROUP BY 1,2,3; COMMIT;